contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint amount) public payable {
        require(address(this).balance >= amount);
        c.fallback{value: amount}();
        uint balBefore = address(c).balance;
        address currentOwner = c.owner();
        bool reverted;
        if (currentOwner == address(this)) {
            c.withdrawAll(recipient);
            reverted = false;
        } else {
            try c.withdrawAll(recipient) { reverted = false; }
            catch { reverted = true; }
